  @attr('string') name;
  @attr('string') data;
}
```
This model will store the CSV data.

### Step 4: Create a new controller for the CSV downloader

In the `controllers` directory, create a new file called `csv-downloader.js`:
```javascript
// controllers/csv-downloader.js
import Controller from '@ember/controller';
import { action } from '@ember/object';

export default class CsvDownloaderController extends Controller {
  @action
  downloadCsv() {
    const csvRecord = this.model;
    const csvData = csvRecord.data;
    const csvBlob = new Blob([csvData], { type: 'text/csv' });
    const csvUrl = URL.createObjectURL(csvBlob);
    const a = document.createElement('a');
    a.href = csvUrl;
    a.download = csvRecord.name + '.csv';
    a.click();
    URL.revokeObjectURL(csvUrl);
  }
}
```
This controller will handle the download of the CSV data.

### Step 5: Create a new web worker for the CSV downloader

In the `workers` directory, create a new file called `csv-downloader.js`:
```javascript
// workers/csv-downloader.js
import { Worker } from 'worker_threads';

const worker = new Worker('./csv-downloader-worker.js', {
  workerData: {
    csvData: 'example data',
  },
});

worker.on('message', (event) => {
  console.log(event.data);
});

worker.on('error', (event) => {
  console.error(event);
});
